Here's the new logic to look up the most specific matching GET/POST/PUT/PATCH/DELETE function. (I have not tested this code. It's a spike that I plan to rewrite with TDD.)

```js
 endpoint(method, url) {
    function findHandler(tree, path, fallback) {
      const handler = tree.script?.[method] ?? fallback;

      if (path.length === 0) {
        return handler;
      }

      if (tree.children[path[0]]) {
        return findHandler(tree.children[path[0]], path.slice(1), handler);
      }

      const wildcard = tree.script?.wildcard?.(path[0]);

      if (wildcard) {
        return findHandler(wildcard, path.slice(1), handler);
      }

      return handler;
    }

    function notFoundFallback() {
      return {
        status: 404,
        body: `${method} method for endpoint at "${url}" does not exist`,
      };
    }

    return findHandler(
      this.moduleTree,
      url.split("/").slice(1),
      notFoundFallback
    );
  }
```

