Here's a pattern so that multiple versions can be served by the same implementation and everything is type safe. 


```ts
// types/versions.ts

export type Versions = "1.0" | "2.0" | "3.0";

export type VersionsGTE = {
  "1.0": "1.0" | "2.0" | "3.0";
  "2.0": "2.0" | "3.0";
  "3.0": "3.0";
};

type VersionMap = Partial<Record<Versions, object>>;

export type Versioned<
  T extends VersionMap,
  V extends keyof T & Versions = keyof T & Versions,
> = T[V] & {
  version: V;
  minVersion<M extends keyof T & Versions>(
    min: M,
  ): this is Versioned<T, Extract<V, VersionsGTE[M]>>;
};

// ./types/paths/some/path.ts

type HTTP_GET_$_Versions = {
  "1.0": {
    foo: string;
  };
  "2.0": {
    foo: string;
    bar: number;
  };
  "3.0": {
    foo: string;
    bar: number;
    baz: boolean;
  };
};

type HTTP_GET_$ = Versioned<HTTP_GET_$_Versions>;

export type HTTP_GET = ($: HTTP_GET_$) => void;

// ./routes/some/path.ts
export const GET: HTTP_GET = ($) => {
  void $.foo;

  if ($.minVersion("2.0")) {
    void $.bar;
  }

  if ($.minVersion("3.0")) {
    void $.baz;
  }
};

```

